// Decide se há que enviar email — lembrete horário enquanto o WhatsApp
// estiver desligado, aviso único quando recupera, e NUNCA entre as 22:00
// e as 08:00 (hora de Lisboa). Pedido do Nuno, 2026-08-29.
const staticData = $getWorkflowStaticData('global');
if (staticData.emFalha === undefined) staticData.emFalha = false;

// $json.instance.state existe no caminho de sucesso; no caminho de erro
// (timeout, DNS, etc.) não há isso — tratamos como 'indisponivel', que
// conta como problema na mesma.
const estadoAtual = ($json.instance && $json.instance.state) || 'indisponivel';
const estaOk = estadoAtual === 'open';

const agora = new Date();
// hourCycle:'h23' evita o bug conhecido do Intl que devolve "24" à meia-noite
// com hour12:false em alguns motores — assim fica sempre 00-23.
const horaLisboa = Number(
  new Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/Lisbon', hour: '2-digit', hourCycle: 'h23' }).format(agora)
);
const emJanelaSilencio = horaLisboa >= 22 || horaLisboa < 8;

let acao = 'nada';

if (!estaOk) {
  staticData.emFalha = true;
  const ultimoAlertaEm = staticData.ultimoAlertaEm;
  const passouUmaHora = !ultimoAlertaEm || (agora.getTime() - new Date(ultimoAlertaEm).getTime()) >= 60 * 60 * 1000;
  if (passouUmaHora && !emJanelaSilencio) {
    acao = 'alertar_falha';
    staticData.ultimoAlertaEm = agora.toISOString();
  }
} else if (estaOk && staticData.emFalha) {
  // Estava em falha e recuperou agora. Se formos apanhados na janela de
  // silêncio, NÃO limpamos emFalha — fica pendente e o aviso de
  // recuperação sai na primeira verificação depois das 08:00.
  if (!emJanelaSilencio) {
    acao = 'alertar_recuperado';
    staticData.emFalha = false;
    staticData.ultimoAlertaEm = null;
  }
}

return [{ json: { estadoAtual, acao, verificadoEm: agora.toISOString() } }];

const estado = $('Avaliar Mudança de Estado').item.json;
const qr = $json.base64 || null; // pode falhar se a instância estiver mesmo incontactável
const quando = new Date(estado.verificadoEm).toLocaleString('pt-PT', { timeZone: 'Europe/Lisbon' });

const imgHtml = qr
  ? '<p><img src="' + qr + '" alt="Código QR" style="width:280px;height:280px;border:1px solid #ddd;" /></p>'
  : '<p><em>Não foi possível gerar o código QR automaticamente — abre o painel da Evolution API para o obter.</em></p>';

const html = '<div style="font-family:sans-serif;max-width:480px;">' +
  '<h2 style="color:#B4756A;">🔴 WhatsApp desligado</h2>' +
  '<p>A ligação do WhatsApp da Essence Wellness (Evolution API) continua em baixo — estado actual: <strong>' + estado.estadoAtual + '</strong>.</p>' +
  '<p>Verificado em: ' + quando + '.</p>' +
  '<p>Nenhuma mensagem de WhatsApp está a sair enquanto isto não for corrigido (os avisos por email de falha individual continuam a funcionar, mas é melhor reconectar).</p>' +
  '<p><strong>Para reconectar:</strong> abre o WhatsApp no telemóvel ligado a este número → Dispositivos Ligados → Ligar Dispositivo → aponta a câmara ao código abaixo.</p>' +
  imgHtml +
  '<p style="color:#999;font-size:12px;">Este lembrete repete-se de hora a hora enquanto o WhatsApp estiver desligado, exceto entre as 22:00 e as 08:00 (não recebes nada durante a noite).</p>' +
  '</div>';

return [{ json: { to: 'geral@essencewellnesspt.com', subject: '🔴 WhatsApp desligado — Evolution API', html } }];

